export const byId = (id: string): Source => {
  const s = SOURCES.find((x) => x.id === id);
  if (!s) throw new Error(`Half: unknown source "${id}"`);
  return s;
};

export function assertNoUnverifiedClaims(): void {
  const bad = SOURCES.filter((s) => s.status === 'needs-check');
  if (bad.length) throw new Error(`Half: unverified sources on screen: ${bad.map((s) => s.id).join(', ')}`);
}
